const{Vec3}=require('vec3'),V=(x,y,z)=>new Vec3(x,y,z),self=bot.entity,hp=bot.health;let c,issue=null,trace=[];const full=p=>bot.blockAt(p)?.shapes?.some(s=>s.join(',')==='0,0,0,1,1,1'),count=n=>bot.inventory.items().filter(i=>i.name===n).reduce((s,i)=>s+i.count,0),tick=async n=>{await bot.waitForTicks(n);if(bot.entity!==self||bot.game.dimension!=='overworld'||bot.health<hp)throw Error('LIFE_HURT')};bot.clearControlStates();bot.pathfinder.setGoal(null);async function move(x,z){for(let k=0;k<60;k++){const p=bot.entity.position,dx=x-p.x,dz=z-p.z;bot.clearControlStates();if(Math.hypot(dx,dz)<.06){await tick(3);return}await bot.lookAt(V(x,p.y+1.4,z),true);bot.setControlState('sneak',true);bot.setControlState('forward',true);await tick(1)}throw Error('BODY_BOUND')}
try{if(bot.game.dimension!=='overworld'||bot.health<20||bot.entity.position.x>=8)throw Error('START');c=await bot.openChest(bot.blockAt(V(7,67,82)));const it=c.containerItems().find(i=>i.name==='gravel');if(!it||it.count<2)throw Error('BANK_GRAVEL2');await c.withdraw(it.type,null,2);c.close();c=null;await tick(6);if(count('gravel')<2)throw Error('OWN_GRAVEL2');for(const x of[7,6]){await move(x+.5,83.5);const q=V(x,68,84),support=q.offset(0,-1,0);if(bot.blockAt(q)?.name!=='spruce_planks'||!full(support))throw Error('HEAD_SUPPORT_CURRENT');await bot.unequip('hand');await bot.dig(bot.blockAt(q),true);await tick(3);await bot.equip(bot.inventory.items().find(i=>i.name==='gravel'),'hand');bot.setControlState('sneak',true);await bot._placeBlockWithOptions(bot.blockAt(support),V(0,1,0),{forceLook:true});bot.clearControlStates();await tick(6);if(bot.blockAt(q)?.name!=='gravel'||!full(q)||!full(support))throw Error('FULL_ACK');trace.push([x,bot.blockAt(q).name,count('spruce_planks')]);}await tick(8);if(count('spruce_planks')<2)throw Error('WOOD_RECEIPT');const r=bot.recipesFor(bot.registry.itemsByName.stick.id,null,1,null)[0];if(!r)throw Error('RECIPE');await bot.craft(r,1,null);if(bot.currentWindow)bot.closeWindow(bot.currentWindow);await tick(5);if(count('stick')<4)throw Error('STICK_RECEIPT');}catch(e){issue=e.message;console.log('ISSUE',issue)}finally{if(c)c.close();bot.clearControlStates();bot.pathfinder.setGoal(null)}return{issue,trace,p:bot.entity.position,hp:bot.health,sticks:count('stick'),inv:bot.inventory.items().map(i=>[i.name,i.count,i.durabilityUsed]),southHeads:[6,7].map(x=>bot.blockAt(V(x,68,84))?.name)};
